import os
import json
import sys
from datetime import datetime

def read_tasks_from_file(file_path):
    try:
        with open(file_path, 'r') as file:
            return [line.strip() for line in file if line.strip()]
    except Exception as e:
        return None, str(e)

def write_tasks_to_file(file_path, tasks):
    try:
        with open(file_path, 'wb') as file:
            json.dump(tasks, file)
    except Exception as e:
        return None, str(e)
    return tasks

def append_to_log(file_path, message):
    try:
        with open(file_path, 'a') as file:
            file.write(f"{message}\n")
    except Exception as e:
        return False, str(e)
    return True

def main():
    tasks_txt = "tasks.txt"
    tasks_bin = "tasks.bin"
    tasks_log = "tasks.log"

    # Read tasks from tasks.txt
    tasks_from_txt, txt_error = read_tasks_from_file(tasks_txt)
    if txt_error:
        timestamp = datetime.utcnow().isoformat()
        append_to_log(tasks_log, f"{timestamp} ERROR: {txt_error}")
        sys.exit(1)

    # Load existing tasks from tasks.bin if it exists
    tasks = []
    if os.path.exists(tasks_bin):
        try:
            with open(tasks_bin, 'rb') as file:
                tasks = json.load(file)
        except Exception as e:
            timestamp = datetime.utcnow().isoformat()
            append_to_log(tasks_log, f"{timestamp} ERROR: {e}")
            sys.exit(1)

    # Append tasks from tasks.txt
    tasks.extend(tasks_from_txt)
    tasks_bin_success, bin_error = write_tasks_to_file(tasks_bin, tasks)
    if bin_error:
        timestamp = datetime.utcnow().isoformat()
        append_to_log(tasks_log, f"{timestamp} ERROR: {bin_error}")
        sys.exit(1)

    # Log the number of tasks appended
    timestamp = datetime.utcnow().isoformat()
    appended_count = len(tasks_from_txt)
    append_to_log(tasks_log, f"{timestamp} {appended_count}")

    # Print total number of tasks
    print(len(tasks))

if __name__ == "__main__":
    main()

