    with open(TASKS_BIN, 'wb') as f:
        json.dump(tasks, f)

def log_message(message):
    timestamp = datetime.datetime.utcnow().isoformat()
    with open(LOG_FILE, 'a') as log_file:
        log_file.write(f'{timestamp} {message}\n') 

def main():
