import os
import sys
import json
from datetime import datetime

def load_tasks():
    tasks = []
    if os.path.exists('tasks.bin'):
        try:
            with open('tasks.bin', 'rb') as f:
                tasks = json.load(f)
        except Exception as e:
            return None, str(e)
    return tasks, None

def save_tasks(tasks):
    try:
        with open('tasks.bin', 'w') as f:
            json.dump(tasks, f)
    except Exception as e:
        return False, str(e)
    return True, None

def process_tasks():
    tasks = []
    error = None

    # Load tasks from binary file if exists
    tasks, error = load_tasks()
    if error:
        return False, error

    # Read tasks from text file
    try:
        with open('tasks.txt', 'r') as f:
            for line in f:
                task = line.strip()
                if task:  # Only add non-empty tasks
                    tasks.append(task)
    except Exception as e:
        error = str(e)
        return False, error

    # Save updated tasks
    success, error = save_tasks(tasks)
    if not success and error:
        return False, error

    return True, None

def log_action(action, error=None):
    timestamp = datetime.utcnow().isoformat()
    log_entry = f"{timestamp} {action}"
    if error:
        log_entry += f" - {error}"
    try:
        with open('tasks.log', 'a') as f:
            f.write(log_entry + '\n')
    except Exception as e:
        sys.exit(1)

def main():
    success, error = process_tasks()
    if not success and error:
        log_action("ERROR", error)
        sys.exit(1)

    total_tasks = len(tasks)
    log_action(f"Total tasks: {total_tasks}")
    print(total_tasks)

if __name__ == "__main__":
    tasks = []
    main()
